const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    // SQLite bindings generated from the system header; the library itself is
    // linked from the system (it ships with macOS and every common Linux distro).
    const c = b.addTranslateC(.{
        .root_source_file = b.path("src/c.h"),
        .target = target,
        .optimize = optimize,
    });
    const c_mod = c.createModule();

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{.{ .name = "c", .module = c_mod }},
    });
    root_module.linkSystemLibrary("sqlite3", .{});

    const exe = b.addExecutable(.{
        .name = "notes",
        .root_module = root_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the server");
    run_step.dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    const run_tests = b.addRunArtifact(tests);
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&run_tests.step);
}

//! Persistent notes storage on top of SQLite.
//!
//! A single connection is shared by all request handlers and guarded by a
//! mutex, which keeps every operation (including multi-statement writes)
//! atomic with respect to the others.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");

const Store = @This();

io: Io,
db: sqlite.Db,
mutex: Io.Mutex = .init,

pub const Error = sqlite.Error || Allocator.Error;

pub const Note = struct {
    id: i64,
    title: []const u8,
    body: []const u8,
    tags: []const []const u8,
};

/// Validated content of a note; `tags` must be sorted and free of duplicates.
pub const NoteInput = struct {
    title: []const u8,
    body: []const u8,
    tags: []const []const u8,
};

pub const ListFilter = struct {
    tag: ?[]const u8 = null,
    query: ?[]const u8 = null,
    after: i64 = 0,
    limit: u32 = 100,
};

pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

pub const Stats = struct {
    notes: i64,
    /// Ordered by count descending, then tag ascending.
    tags: []const TagCount,
};

const schema =
    \\CREATE TABLE IF NOT EXISTS notes (
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL
    \\);
    \\CREATE TABLE IF NOT EXISTS note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    \\    tag     TEXT NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) WITHOUT ROWID;
    \\CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags (tag, note_id);
;

pub fn open(io: Io, path: [:0]const u8) sqlite.Error!Store {
    const db = try sqlite.Db.open(path);
    errdefer db.close();
    try db.exec("PRAGMA busy_timeout = 5000");
    // The schema is created before switching to WAL so that the main database
    // file is fully initialized on disk right away.
    try db.exec(schema);
    try db.exec("PRAGMA journal_mode = WAL");
    try db.exec("PRAGMA synchronous = NORMAL");
    try db.exec("PRAGMA foreign_keys = ON");
    return .{ .io = io, .db = db };
}

pub fn close(store: *Store) void {
    store.db.close();
    store.* = undefined;
}

/// Stores a new note. The returned note refers to the memory of `input`.
pub fn create(store: *Store, input: NoteInput) Error!Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    const ins = try store.db.prepare("INSERT INTO notes (title, body) VALUES (?1, ?2)");
    defer ins.finalize();
    try ins.bindAll(.{ input.title, input.body });
    try ins.run();
    const id = store.db.lastInsertRowId();

    try store.insertTags(id, input.tags);
    try store.db.exec("COMMIT");
    return noteFromInput(id, input);
}

pub fn get(store: *Store, arena: Allocator, id: i64) Error!?Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    const sel = try store.db.prepare("SELECT title, body FROM notes WHERE id = ?1");
    defer sel.finalize();
    try sel.bind(1, id);
    if (!try sel.step()) return null;

    const tags_stmt = try store.prepareTagsQuery();
    defer tags_stmt.finalize();
    return .{
        .id = id,
        .title = try arena.dupe(u8, sel.columnText(0)),
        .body = try arena.dupe(u8, sel.columnText(1)),
        .tags = try readTags(arena, tags_stmt, id),
    };
}

/// Replaces a note's content; returns null if the note does not exist.
/// The returned note refers to the memory of `input`.
pub fn update(store: *Store, id: i64, input: NoteInput) Error!?Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    const upd = try store.db.prepare("UPDATE notes SET title = ?1, body = ?2 WHERE id = ?3");
    defer upd.finalize();
    try upd.bindAll(.{ input.title, input.body, id });
    try upd.run();
    if (store.db.changes() == 0) {
        store.rollback();
        return null;
    }

    const del = try store.db.prepare("DELETE FROM note_tags WHERE note_id = ?1");
    defer del.finalize();
    try del.bind(1, id);
    try del.run();

    try store.insertTags(id, input.tags);
    try store.db.exec("COMMIT");
    return noteFromInput(id, input);
}

/// Deletes a note; returns false if it does not exist.
pub fn delete(store: *Store, id: i64) Error!bool {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    try store.db.exec("BEGIN IMMEDIATE");
    errdefer store.rollback();

    const del_tags = try store.db.prepare("DELETE FROM note_tags WHERE note_id = ?1");
    defer del_tags.finalize();
    try del_tags.bind(1, id);
    try del_tags.run();

    const del = try store.db.prepare("DELETE FROM notes WHERE id = ?1");
    defer del.finalize();
    try del.bind(1, id);
    try del.run();
    const found = store.db.changes() > 0;

    try store.db.exec("COMMIT");
    return found;
}

pub fn list(store: *Store, arena: Allocator, filter: ListFilter) Error![]Note {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    // SQLite's built-in lower() folds ASCII letters only, which is exactly the
    // case-insensitivity the API promises.
    const sel = try store.db.prepare(
        \\SELECT id, title, body FROM notes
        \\WHERE id > ?1
        \\  AND (?2 IS NULL OR EXISTS (
        \\        SELECT 1 FROM note_tags WHERE note_id = notes.id AND tag = ?2))
        \\  AND (?3 IS NULL OR instr(lower(title), lower(?3)) > 0
        \\                  OR instr(lower(body), lower(?3)) > 0)
        \\ORDER BY id
        \\LIMIT ?4
    );
    defer sel.finalize();
    try sel.bindAll(.{ filter.after, filter.tag, filter.query, filter.limit });

    const tags_stmt = try store.prepareTagsQuery();
    defer tags_stmt.finalize();

    var notes: std.ArrayList(Note) = .empty;
    while (try sel.step()) {
        const id = sel.columnInt(0);
        try notes.append(arena, .{
            .id = id,
            .title = try arena.dupe(u8, sel.columnText(1)),
            .body = try arena.dupe(u8, sel.columnText(2)),
            .tags = try readTags(arena, tags_stmt, id),
        });
    }
    return notes.items;
}

pub fn stats(store: *Store, arena: Allocator) Error!Stats {
    store.mutex.lockUncancelable(store.io);
    defer store.mutex.unlock(store.io);

    const count = try store.db.prepare("SELECT count(*) FROM notes");
    defer count.finalize();
    _ = try count.step();
    const notes = count.columnInt(0);

    const sel = try store.db.prepare(
        \\SELECT tag, count(*) AS n FROM note_tags
        \\GROUP BY tag
        \\ORDER BY n DESC, tag ASC
    );
    defer sel.finalize();

    var tags: std.ArrayList(TagCount) = .empty;
    while (try sel.step()) {
        try tags.append(arena, .{
            .tag = try arena.dupe(u8, sel.columnText(0)),
            .count = sel.columnInt(1),
        });
    }
    return .{ .notes = notes, .tags = tags.items };
}

fn insertTags(store: *Store, id: i64, tags: []const []const u8) sqlite.Error!void {
    if (tags.len == 0) return;
    const ins = try store.db.prepare("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)");
    defer ins.finalize();
    for (tags) |tag| {
        try ins.bindAll(.{ id, tag });
        try ins.run();
        ins.reset();
    }
}

fn prepareTagsQuery(store: *Store) sqlite.Error!sqlite.Statement {
    return store.db.prepare("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY tag");
}

fn readTags(arena: Allocator, stmt: sqlite.Statement, id: i64) Error![]const []const u8 {
    defer stmt.reset();
    try stmt.bind(1, id);
    var tags: std.ArrayList([]const u8) = .empty;
    while (try stmt.step()) {
        try tags.append(arena, try arena.dupe(u8, stmt.columnText(0)));
    }
    return tags.items;
}

fn rollback(store: *Store) void {
    store.db.exec("ROLLBACK") catch {};
}

fn noteFromInput(id: i64, input: NoteInput) Note {
    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

const testing = std.testing;

test "create, get, update, delete and list" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const a = try store.create(.{ .title = "Hello", .body = "World", .tags = &.{ "a", "b" } });
    const b = try store.create(.{ .title = "other", .body = "", .tags = &.{"b"} });
    try testing.expectEqual(@as(i64, 1), a.id);
    try testing.expectEqual(@as(i64, 2), b.id);

    const got = (try store.get(arena, 1)).?;
    try testing.expectEqualStrings("Hello", got.title);
    try testing.expectEqual(@as(usize, 2), got.tags.len);
    try testing.expectEqualStrings("b", got.tags[1]);

    try testing.expectEqual(@as(usize, 1), (try store.list(arena, .{ .query = "WORLD" })).len);
    try testing.expectEqual(@as(usize, 2), (try store.list(arena, .{ .tag = "b" })).len);
    try testing.expectEqual(@as(usize, 1), (try store.list(arena, .{ .after = 1 })).len);
    try testing.expectEqual(@as(usize, 1), (try store.list(arena, .{ .limit = 1 })).len);

    const s = try store.stats(arena);
    try testing.expectEqual(@as(i64, 2), s.notes);
    try testing.expectEqualStrings("b", s.tags[0].tag);
    try testing.expectEqual(@as(i64, 2), s.tags[0].count);

    try testing.expect((try store.update(1, .{ .title = "x", .body = "", .tags = &.{} })) != null);
    try testing.expect((try store.update(9, .{ .title = "x", .body = "", .tags = &.{} })) == null);
    try testing.expect(try store.delete(2));
    try testing.expect(!try store.delete(2));
    try testing.expectEqual(@as(usize, 0), (try store.stats(arena)).tags.len);

    // Ids are never reused.
    const c = try store.create(.{ .title = "c", .body = "", .tags = &.{} });
    try testing.expectEqual(@as(i64, 3), c.id);
}

//! HTTP routing and handlers, independent of the transport.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Status = std.http.Status;
const Method = std.http.Method;
const Stringify = std.json.Stringify;
const Store = @import("Store.zig");
const validate = @import("validate.zig");

pub const Request = struct {
    method: Method,
    /// Request target: path plus optional `?query`.
    target: []const u8,
    body: []const u8,
};

pub const Response = struct {
    status: Status,
    content_type: []const u8 = "application/json",
    body: []const u8 = "",
};

/// Computes the response to a request. Only storage failures and allocation
/// failures are returned as errors.
pub fn handle(store: *Store, arena: Allocator, req: Request) Store.Error!Response {
    const qmark = std.mem.findScalar(u8, req.target, '?');
    const path = req.target[0 .. qmark orelse req.target.len];
    const query = if (qmark) |i| req.target[i + 1 ..] else "";

    if (std.mem.eql(u8, path, "/health")) {
        if (req.method != .GET) return methodNotAllowed(arena);
        return .{ .status = .ok, .content_type = "text/plain; charset=utf-8", .body = "ok" };
    }
    if (std.mem.eql(u8, path, "/notes")) return switch (req.method) {
        .GET => listNotes(store, arena, query),
        .POST => createNote(store, arena, req.body),
        else => methodNotAllowed(arena),
    };
    if (std.mem.startsWith(u8, path, "/notes/")) {
        const segment = path["/notes/".len..];
        const id = validate.noteId(segment) orelse return notFound(arena);
        return switch (req.method) {
            .GET => getNote(store, arena, id),
            .PUT => updateNote(store, arena, id, req.body),
            .DELETE => deleteNote(store, id, arena),
            else => methodNotAllowed(arena),
        };
    }
    if (std.mem.eql(u8, path, "/stats")) {
        if (req.method != .GET) return methodNotAllowed(arena);
        return stats(store, arena);
    }
    if (std.mem.eql(u8, path, "/tags")) {
        if (req.method != .GET) return methodNotAllowed(arena);
        return tags(store, arena);
    }
    return notFound(arena);
}

fn createNote(store: *Store, arena: Allocator, body: []const u8) Store.Error!Response {
    var failure: validate.Failure = undefined;
    const input = validate.noteInput(arena, body, &failure) catch |err| switch (err) {
        error.Invalid => return errorResponse(arena, .bad_request, failure.message),
        error.OutOfMemory => return error.OutOfMemory,
    };
    const note = try store.create(input);
    return json(arena, .created, note);
}

fn getNote(store: *Store, arena: Allocator, id: i64) Store.Error!Response {
    const note = try store.get(arena, id) orelse return notFound(arena);
    return json(arena, .ok, note);
}

fn updateNote(store: *Store, arena: Allocator, id: i64, body: []const u8) Store.Error!Response {
    var failure: validate.Failure = undefined;
    const input = validate.noteInput(arena, body, &failure) catch |err| switch (err) {
        error.Invalid => return errorResponse(arena, .bad_request, failure.message),
        error.OutOfMemory => return error.OutOfMemory,
    };
    const note = try store.update(id, input) orelse return notFound(arena);
    return json(arena, .ok, note);
}

fn deleteNote(store: *Store, id: i64, arena: Allocator) Store.Error!Response {
    if (!try store.delete(id)) return notFound(arena);
    return .{ .status = .no_content };
}

fn listNotes(store: *Store, arena: Allocator, query: []const u8) Store.Error!Response {
    var failure: validate.Failure = undefined;
    const filter = validate.listFilter(arena, query, &failure) catch |err| switch (err) {
        error.Invalid => return errorResponse(arena, .bad_request, failure.message),
        error.OutOfMemory => return error.OutOfMemory,
    };
    const notes = try store.list(arena, filter);
    return json(arena, .ok, .{ .notes = notes });
}

fn stats(store: *Store, arena: Allocator) Store.Error!Response {
    const s = try store.stats(arena);
    var out: std.Io.Writer.Allocating = .init(arena);
    var w: Stringify = .{ .writer = &out.writer };
    writeStats(&w, s) catch return error.OutOfMemory;
    return .{ .status = .ok, .body = out.written() };
}

fn writeStats(w: *Stringify, s: Store.Stats) Stringify.Error!void {
    try w.beginObject();
    try w.objectField("notes");
    try w.write(s.notes);
    try w.objectField("tags");
    try w.beginObject();
    for (s.tags) |t| {
        try w.objectField(t.tag);
        try w.write(t.count);
    }
    try w.endObject();
    try w.endObject();
}

fn tags(store: *Store, arena: Allocator) Store.Error!Response {
    const s = try store.stats(arena);
    return json(arena, .ok, .{ .tags = s.tags });
}

fn json(arena: Allocator, status: Status, value: anytype) Allocator.Error!Response {
    const body = try Stringify.valueAlloc(arena, value, .{});
    return .{ .status = status, .body = body };
}

fn errorResponse(arena: Allocator, status: Status, message: []const u8) Allocator.Error!Response {
    return json(arena, status, .{ .@"error" = message });
}

fn notFound(arena: Allocator) Allocator.Error!Response {
    return errorResponse(arena, .not_found, "not found");
}

fn methodNotAllowed(arena: Allocator) Allocator.Error!Response {
    return errorResponse(arena, .method_not_allowed, "method not allowed");
}

const testing = std.testing;

const TestEnv = struct {
    store: Store,
    arena: std.heap.ArenaAllocator,

    fn init() !TestEnv {
        return .{
            .store = try Store.open(testing.io, ":memory:"),
            .arena = .init(testing.allocator),
        };
    }

    fn deinit(env: *TestEnv) void {
        env.store.close();
        env.arena.deinit();
    }

    fn call(env: *TestEnv, method: Method, target: []const u8, body: []const u8) !Response {
        return handle(&env.store, env.arena.allocator(), .{ .method = method, .target = target, .body = body });
    }
};

test "routing and status codes" {
    var env = try TestEnv.init();
    defer env.deinit();

    try testing.expectEqual(Status.ok, (try env.call(.GET, "/health", "")).status);
    try testing.expectEqual(Status.not_found, (try env.call(.GET, "/nope", "")).status);
    try testing.expectEqual(Status.method_not_allowed, (try env.call(.DELETE, "/notes", "")).status);
    try testing.expectEqual(Status.method_not_allowed, (try env.call(.POST, "/stats", "")).status);
    try testing.expectEqual(Status.not_found, (try env.call(.GET, "/notes/abc", "")).status);
    try testing.expectEqual(Status.not_found, (try env.call(.GET, "/notes/1", "")).status);

    const created = try env.call(.POST, "/notes", "{\"title\":\"a\",\"tags\":[\"y\",\"x\"]}");
    try testing.expectEqual(Status.created, created.status);
    try testing.expectEqualStrings("{\"id\":1,\"title\":\"a\",\"body\":\"\",\"tags\":[\"x\",\"y\"]}", created.body);

    try testing.expectEqual(Status.method_not_allowed, (try env.call(.POST, "/notes/1", "")).status);
    try testing.expectEqual(Status.bad_request, (try env.call(.GET, "/notes?limit=0", "")).status);

    const s = try env.call(.GET, "/stats", "");
    try testing.expectEqualStrings("{\"notes\":1,\"tags\":{\"x\":1,\"y\":1}}", s.body);

    const t = try env.call(.GET, "/tags", "");
    try testing.expectEqualStrings("{\"tags\":[{\"tag\":\"x\",\"count\":1},{\"tag\":\"y\",\"count\":1}]}", t.body);

    try testing.expectEqual(Status.no_content, (try env.call(.DELETE, "/notes/1", "")).status);
    try testing.expectEqualStrings("{\"notes\":[]}", (try env.call(.GET, "/notes", "")).body);
}

//! notes: a small HTTP notes service backed by SQLite.
//!
//! Usage: NOTES_DB=<path> notes <port>

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const Store = @import("Store.zig");
const api = @import("api.zig");

const log = std.log.scoped(.notes);

/// Largest request body accepted; larger bodies are rejected with 413.
const max_body_len = 32 * 1024 * 1024;
/// Also bounds the size of the request head.
const recv_buffer_len = 64 * 1024;
const send_buffer_len = 16 * 1024;

const App = struct {
    io: Io,
    gpa: Allocator,
    store: *Store,
};

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const arena = init.arena.allocator();

    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 2) {
        log.err("usage: {s} <port>", .{if (args.len > 0) args[0] else "notes"});
        return error.InvalidArguments;
    }
    const port = std.fmt.parseInt(u16, args[1], 10) catch {
        log.err("invalid port: {s}", .{args[1]});
        return error.InvalidArguments;
    };
    const db_path = init.environ_map.get("NOTES_DB") orelse {
        log.err("the NOTES_DB environment variable must name the database file", .{});
        return error.MissingDatabasePath;
    };

    var store = try Store.open(io, try arena.dupeZ(u8, db_path));
    defer store.close();

    const address = try Io.net.IpAddress.parseIp4("127.0.0.1", port);
    var server = try address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 });
    defer server.deinit(io);

    const app: App = .{ .io = io, .gpa = init.gpa, .store = &store };

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.Canceled => return,
            else => {
                log.warn("accept failed: {t}", .{err});
                continue;
            },
        };
        connections.concurrent(io, serveConnection, .{ &app, stream }) catch {
            // No spare unit of concurrency: serve on this thread instead.
            serveConnection(&app, stream);
        };
    }
}

fn serveConnection(app: *const App, stream: Io.net.Stream) void {
    const io = app.io;
    defer stream.close(io);

    var recv_buffer: [recv_buffer_len]u8 = undefined;
    var send_buffer: [send_buffer_len]u8 = undefined;
    var reader = stream.reader(io, &recv_buffer);
    var writer = stream.writer(io, &send_buffer);
    var http: std.http.Server = .init(&reader.interface, &writer.interface);

    var arena_state: std.heap.ArenaAllocator = .init(app.gpa);
    defer arena_state.deinit();

    while (true) {
        _ = arena_state.reset(.retain_capacity);
        var request = http.receiveHead() catch |err| switch (err) {
            error.HttpConnectionClosing => return,
            else => {
                log.debug("receiving request head failed: {t}", .{err});
                return;
            },
        };
        serveRequest(app, arena_state.allocator(), &request) catch |err| {
            log.debug("serving request failed: {t}", .{err});
            return;
        };
        if (!request.head.keep_alive) return;
    }
}

fn serveRequest(app: *const App, arena: Allocator, request: *std.http.Server.Request) !void {
    const method = request.head.method;
    // Reading the body invalidates the strings of the request head.
    const target = try arena.dupe(u8, request.head.target);
    const keep_alive = request.head.keep_alive;

    const body = readBody(arena, request) catch |err| switch (err) {
        error.StreamTooLong => return respond(request, .{
            .status = .payload_too_large,
            .body = "{\"error\":\"request body too large\"}",
        }, false),
        else => return err,
    };

    const response = api.handle(app.store, arena, .{
        .method = method,
        .target = target,
        .body = body,
    }) catch |err| blk: {
        log.err("{s} {s}: {t}", .{ @tagName(method), target, err });
        break :blk api.Response{
            .status = .internal_server_error,
            .body = "{\"error\":\"internal server error\"}",
        };
    };
    try respond(request, response, keep_alive);
}

fn readBody(arena: Allocator, request: *std.http.Server.Request) ![]const u8 {
    const head = &request.head;
    if (!head.method.requestHasBody()) return "";
    // Without a length or chunked encoding, a request has no body; say so
    // explicitly, since `std.http.Server` would otherwise read until EOF.
    if (head.content_length == null and head.transfer_encoding == .none) head.content_length = 0;
    const body_reader = try request.readerExpectContinue(&.{});
    return body_reader.allocRemaining(arena, .limited(max_body_len)) catch |err| switch (err) {
        error.ReadFailed => request.server.reader.body_err orelse error.ReadFailed,
        else => |e| e,
    };
}

fn respond(request: *std.http.Server.Request, response: api.Response, keep_alive: bool) !void {
    try request.respond(response.body, .{
        .status = response.status,
        .keep_alive = keep_alive,
        .extra_headers = &.{.{ .name = "content-type", .value = response.content_type }},
    });
}

